# A2-06 · recall@k: qué proporción de relevantes (ids que responden) está entre
# los k primeros de ranking (los ids que devuelve el buscador, del mejor al peor).

def recall_en_k(ranking, relevantes, k):
    primeros = ranking   # ← cambia esta línea: quédate solo con los k primeros
    encontrados = 0
    for doc in relevantes:
        if doc in primeros:
            encontrados += 1
    return encontrados / len(relevantes)

# Pruébala con py run. Debería imprimir 0.5:
print(recall_en_k(["funda", "garantia", "cera", "envios"], ["garantia", "envios"], 3))

# Completa la línea marcada y compruébala con py check.
def rango_reciproco(recuperados, relevantes):
    for pos, doc in enumerate(recuperados):
        if doc in relevantes:
            return 0   # ← cambia esta línea: 1 / posición, contando desde 1
    return 0.0

print(rango_reciproco(["x", "bueno", "y"], ["bueno"]))   # 0.5
